    #[test]
    fn pandoc_cli_option_errors() {
        let fs = MemoryVfs::new();
        let columns = "Argument of --columns must be a number greater than 0\n";
        let wrap = "--wrap must be auto, none, or preserve\n";
        let mut cases = vec![
            (args(&["--columns"]), "option `--columns' requires an argument NUMBER\nTry pandoc --help for more information.\n"),
            (args(&["--wrap"]), "option `--wrap' requires an argument auto|none|preserve\nTry pandoc --help for more information.\n"),
            (args(&["--columns=0", "--wrap"]), "option `--wrap' requires an argument auto|none|preserve\nTry pandoc --help for more information.\n"),
            (args(&["--wrap=bad", "--columns"]), "option `--columns' requires an argument NUMBER\nTry pandoc --help for more information.\n"),
            (args(&["--columns=0", "--wrap=bad"]), columns),
            (args(&["--wrap=bad", "--columns=0"]), wrap),
            (args(&["--columns", "--wrap"]), columns),
            (args(&["--columns=8", "--columns=0"]), columns),
        ];
        for (option, values, message) in [
            ("--columns", vec!["0", "-1", "bad", "", "1.5", "1e2", "+2"], columns),
            ("--wrap", vec!["bad", "", "AUTO", "--columns"], wrap),
        ] {
            for value in values {
                cases.push((args(&[option, value]), message));
                cases.push((vec![format!("{option}={value}")], message));
            }
        }
        for (options, message) in cases {
            for output in [vec![], args(&["-o", "/result"])] {
                fs.write_file("/result", b"existing output").unwrap();
                let mut argv = args(&["-f", "gfm", "-t", "plain"]);
                argv.extend(output);
                argv.extend(options.clone());
                let result = cmd_pandoc(&argv, "hello", "/", &fs);
                assert_eq!(result.exit_code, 6);
                assert_eq!(result.stdout, "");
                assert_eq!(result.stderr, message);
                assert_eq!(fs.read_file("/result").unwrap(), b"existing output");
            }
        }
    }

    #[test]
    fn sqlite_cli_checks_options_before_opening_and_preserves_readonly_databases() {
        let fs = MemoryVfs::new();
        let run = |argv: &[&str]| cmd_sqlite3(&args(argv), "", "/", &fs);
        let bad = run(&["--bad", "/db", "CREATE TABLE t(x)"]);
        assert_eq!((bad.exit_code, bad.stderr.as_str()), (1, "sqlite3: Error: unknown option: --bad\n"));
        assert!(fs.stat("/db").is_err());
        assert_eq!(run(&["--readonly", "/missing", "SELECT 1"]).stdout, "1\n");
        assert!(fs.stat("/missing").is_err());
        assert_eq!(run(&["/db", "CREATE TABLE t(x); INSERT INTO t VALUES(1)"]).exit_code, 0);
        fs.set_times("/db", None, Some(123.)).unwrap();
        let before = fs.read_file("/db").unwrap();
        for sql in ["/*comment*/ INSERT INTO t VALUES(2)", "WITH s AS (SELECT 2) INSERT INTO t SELECT * FROM s",
            "PRAGMA user_version=2", ".import /data t", ".restore /backup"] {
            let denied = run(&["--readonly", "/db", sql]);
            assert_eq!((denied.exit_code, denied.stderr.as_str()), (1, "Error: attempt to write a readonly database\n"), "{sql}");
        }
        assert_eq!(run(&["--header", "--csv", "/db", "SELECT * FROM t"]).stdout, "x\n1\n");
        assert_eq!(fs.read_file("/db").unwrap(), before);
        assert_eq!(fs.stat("/db").unwrap().mtime_ms, 123.);
    }

    #[test]
    fn sqlite_binary_format3_header_and_btree_roundtrip() {
        let vfs = MemoryVfs::new();
        vfs.mkdir_all("/db").unwrap();
        let out1 = cmd_sqlite3(
            &args(&[
                "/db/test.sqlite",
                "CREATE TABLE items (id INTEGER PRIMARY KEY, name TEXT, qty INT); INSERT INTO items VALUES (1, 'bolt', 50), (2, 'nut', 120);",
            ]),
            "",
            "/db",
            &vfs,
        );
        assert_eq!(out1.exit_code, 0, "stderr: {}", out1.stderr);

        let raw = vfs.read_file("/db/test.sqlite").unwrap();
        assert_eq!(&raw[..16], b"SQLite format 3\0");
        assert_eq!(raw.len() % 4096, 0);
        assert!(raw.len() >= 8192);
        // Page 1 at offset 100 is a leaf or interior table B-tree page (0x0d or 0x05), never '{'
        assert!(raw[100] == 0x0d || raw[100] == 0x05);
        assert_ne!(raw[16], b'{');

        let out2 = cmd_sqlite3(
            &args(&["/db/test.sqlite", "SELECT name, qty FROM items ORDER BY id;"]),
            "",
            "/db",
            &vfs,
        );
        assert_eq!(out2.exit_code, 0);
        assert_eq!(out2.stdout, "bolt|50\nnut|120\n");
    }

    #[test]
    fn sqlite_multipage_btree_persistence_over_120_rows() {
        let vfs = MemoryVfs::new();
        vfs.mkdir_all("/db").unwrap();
        let mut sql = String::from("CREATE TABLE logs (id INTEGER PRIMARY KEY, msg TEXT);");
        for i in 1..=120 {
            sql.push_str(&format!(
                "INSERT INTO logs VALUES ({i}, 'payload-entry-number-{i:04}-padding-text');"
            ));
        }
        let init = cmd_sqlite3(&args(&["/db/multi.db", &sql]), "", "/db", &vfs);
        assert_eq!(init.exit_code, 0);
        let bytes = vfs.read_file("/db/multi.db").unwrap();
        assert_eq!(bytes.len() % 4096, 0);
        assert!(bytes.len() >= 12288, "expected >= 3 pages, got {}", bytes.len());

        let check = cmd_sqlite3(
            &args(&[
                "/db/multi.db",
                "SELECT COUNT(*), MIN(id), MAX(id) FROM logs;",
            ]),
            "",
            "/db",
            &vfs,
        );
        assert_eq!(check.exit_code, 0);
        assert_eq!(check.stdout.trim(), "120|1|120");
    }

    #[test]
    fn sqlite_cte_window_functions_group_by_and_triggers() {
        let vfs = MemoryVfs::new();
        vfs.mkdir_all("/db").unwrap();
        let setup = cmd_sqlite3(
            &args(&[
                "/db/win.db",
                "CREATE TABLE sales (team TEXT, amount INT);
                 CREATE TABLE audit (entry TEXT);
                 CREATE TRIGGER tr_sales AFTER INSERT ON sales BEGIN
                   INSERT INTO audit VALUES (NEW.team || ':' || NEW.amount);
                 END;
                 INSERT INTO sales VALUES ('alpha', 100), ('alpha', 50), ('beta', 200), ('gamma', 150);",
            ]),
            "",
            "/db",
            &vfs,
        );
        assert_eq!(setup.exit_code, 0);

        let query = cmd_sqlite3(
            &args(&[
                "/db/win.db",
                "WITH ranked AS (
                   SELECT team, SUM(amount) AS total, RANK() OVER (ORDER BY SUM(amount) DESC) AS rnk, DENSE_RANK() OVER (ORDER BY SUM(amount) DESC) AS drnk
                   FROM sales GROUP BY team
                 )
                 SELECT team, total, rnk, drnk FROM ranked ORDER BY rnk, team;",
            ]),
            "",
            "/db",
            &vfs,
        );
        assert_eq!(query.exit_code, 0);
        assert_eq!(
            query.stdout.trim(),
            "beta|200|1|1\nalpha|150|2|2\ngamma|150|2|2"
        );
    }

