    #[test]
    fn mmdc_keeps_existing_files_when_graph_rendering_exceeds_the_budget() {
        let (mut shell, fs) = crate::shell::Shell::with_memory_fs();
        shell.set_limits(crate::budget::ShellLimits { max_input_bytes: 1200, ..Default::default() });
        fs.write_file("/chart.mmd", b"flowchart TD; A; B; C; D; E").unwrap();
        for path in ["/output.svg","/output.png","/output.pdf"] {
            fs.write_file(path,b"previous").unwrap();
            let result=shell.exec(&format!("mmdc -i /chart.mmd -o {path}")).unwrap();
            assert_eq!(result.exit_code,1,"{path}: {}",result.stderr);
            assert_eq!(result.stderr,"mmdc: E_LIMIT: Render work budget exceeded\n");
            assert_eq!(fs.read_file(path).unwrap(),b"previous");
        }
    }

    fn assert_mermaid_outputs(cases: &[(&str, &str, &str)]) {
        let fs = MemoryVfs::new();
        for &(source, format, expected) in cases {
            let path = format!("/chart.{format}");
            fs.write_file(&path, b"previous").unwrap();
            let result = try_run_structured_command("mmdc", &args(&["-i", "-", "-o", &path]), source, "/", &BTreeMap::new(), &fs).unwrap();
            let bytes = fs.read_file(&path).unwrap();
            if expected.starts_with("mmdc:") {
                assert_eq!(result.stderr, expected, "{source}");
                assert_eq!(result.exit_code, if expected.starts_with("mmdc: E_CONFIG:") {2} else {1});
                assert_eq!(bytes, b"previous");
            } else {
                assert_eq!(result.exit_code, 0, "{}", result.stderr);
                assert_eq!(crate::commands::archive::sha256_bytes(&bytes).iter().map(|b| format!("{b:02x}")).collect::<String>(), expected, "{format}: {source}");
            }
        }
    }

    #[test]
    fn mmdc_reads_frontmatter_preserving_body_positions_and_title_precedence() {
        let fs=MemoryVfs::new();
        for (source,status,expected) in [
            ("---\ntitle: Example\n---\n  notDiagram foo",1,"mmdc: E_UNSUPPORTED (line 4, column 3): Unsupported or unrecognized Mermaid diagram family 'notDiagram'\n"),
            ("---\ntitle: Ship\n---\npie\n\"A\":3\n\"B\":1",0,"5dac237225b856092ed1a1d19f6ea209b6d1f23b9b4ae90374870bb3bdcda157"),
            ("---\ntitle: Test ü\nconfig: {rankGap: 95, theme: forest}\n---\nflowchart TD; A[Build release] -->|review| B{Ship?}; B --> C & D",0,"938a4e4a3b9c802b6e7888f78a3d150c3cda6d688eeb157d448359b730c6a6b3"),
            ("---\ntitle: metadata\nconfig: {theme: forest}\n---\n%%{init: {theme: dark}}%%\nflowchart TD; title body overrides; A-->B",0,"953609ca74d2e706ee352a1ef7a721dfd3fba683f8465e998ba65b081a627ea2"),
            ("---\ntitle: 😀\n---\nflowchart TD; A-->",1,"mmdc: E_SYNTAX (line 4, column 19): Expected node identifier at ''\n"),
            ("---\ntitle: \"<img src=X>\"\n---\nflowchart TD; A[Build release] -->|review| B{Ship?}; B --> C & D",1,"mmdc: E_UNSUPPORTED: Unsupported HTML or active content '<img' in diagram label\n"),
            ("---\ntitle: Hello\nflowchart TD; A[Build release] -->|review| B{Ship?}; B --> C & D",1,"mmdc: E_SYNTAX: Unclosed YAML frontmatter\n"),
            ("---\ntitle: Only\n---",1,"mmdc: E_SYNTAX (line 1, column 1): Diagram source is empty\n"),
        ] {
            fs.write_file("/d.svg",b"previous").unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-o","/d.svg"]),source,"/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(r.exit_code,status,"{}",r.stderr);
            let bytes=fs.read_file("/d.svg").unwrap();
            if status==0 {
                assert_eq!(crate::commands::archive::sha256_bytes(&bytes).iter().map(|b|format!("{b:02x}")).collect::<String>(),expected);
            }else{
                assert_eq!(r.stderr,expected);
                assert_eq!(bytes,b"previous");
            }
        }
    }

    #[test]
    fn mmdc_resolves_init_directives_as_yaml_mappings() {
        let fs=MemoryVfs::new();
        let chart="flowchart TD; A[Build release] -->|review| B; B-->C & D";
        for (directives,file,expected) in [
            ("%%{other: {theme: dark}}%%\n%%{init: {description: 'dark'}}%%","{}","{}"),
            ("%%{init: {theme: forest, flowchart: {wrappingWidth: 30, nodeSpacing: 74}}}%%\n%%{initialize: {flowchart: {rankSpacing: 89}}}%%",r#"{"theme":"dark","width":310}"#,r#"{"theme":"forest","width":310,"flowchart":{"wrappingWidth":30,"nodeSpacing":74,"rankSpacing":89}}"#),
            ("%%{init: {rankGap: 72, width: 180, backgroundColor: 'navy'}}%%",r#"{"width":230,"flowchart":{"rankSpacing":90}}"#,r#"{"rankGap":90,"width":230,"backgroundColor":"navy"}"#),
        ] {
            let mut outputs=Vec::new();
            for (config,source) in [(file,format!("{directives}\n{chart}")),(expected,chart.to_owned())] {
                fs.write_file("/c",config.as_bytes()).unwrap();
                let r=try_run_structured_command("mmdc",&args(&["-i","-","-c","/c","-o","/d.svg"]),&source,"/",&BTreeMap::new(),&fs).unwrap();
                assert_eq!(r.exit_code,0,"{}",r.stderr);
                outputs.push(fs.read_file("/d.svg").unwrap());
            }
            assert_eq!(outputs[0],outputs[1],"{directives}");
        }
        for (yaml,message) in [("[]","Mermaid configuration must be a mapping"),("{theme: wrong}","Unsupported theme 'wrong' in config file"),("{ a: [ }","Flow sequence in block collection must be sufficiently indented and end with a ] at line 1, column 9:\n\n { a: [ }\n        ^\n")] {
            fs.write_file("/d.svg",b"previous").unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-o","/d.svg"]),&format!("%%{{init: {yaml}}}%%\n{chart}"),"/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(r.exit_code,2);
            assert_eq!(r.stderr,format!("mmdc: E_CONFIG: {message}\n"));
            assert_eq!(fs.read_file("/d.svg").unwrap(),b"previous");
        }
    }

    #[test]
    fn mmdc_validates_config_before_layout_and_keeps_the_output_on_error() {
        let fs=MemoryVfs::new();
        for (config,message) in [
            (r#"{"width":-1,"extra":0}"#,"E_CONFIG: Unknown configuration key 'extra'"),
            (r#"{"theme":{"mode":["bad"]}}"#,"E_CONFIG: Unsupported theme mode 'bad'"),
            (r#"{"theme":{"light":null}}"#,"E_CONFIG: Theme configuration 'light' must be an object"),
            (r#"{"width":1.5,"backgroundColor":"bogus"}"#,"E_ARGUMENT: Viewport width must be a positive integer"),
            (r#"{"height":9007199254740992}"#,"E_ARGUMENT: Viewport height must be a positive integer"),
        ]{
            fs.write_file("/c",config.as_bytes()).unwrap();
            fs.write_file("/d.svg",b"previous").unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-c","/c","-o","/d.svg"]),"flowchart TD; A-->B","/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!((r.exit_code,r.stderr),(2,format!("mmdc: {message}\n")));
            assert_eq!(fs.read_file("/d.svg").unwrap(),b"previous");
        }
        fs.write_file("/c","\u{feff}{\"width\":4294967296,\"themeVariables\":null,\"flowchart\":null}".as_bytes()).unwrap();
        let r=try_run_structured_command("mmdc",&args(&["-i","-","-c","/c","-o","-"]),"flowchart TD; A-->B","/",&BTreeMap::new(),&fs).unwrap();
        assert_eq!(r.exit_code,0,"{}",r.stderr);
        assert!(r.stdout.starts_with(r#"<svg xmlns="http://www.w3.org/2000/svg" width="4294967296""#));
    }

    #[test]
    fn mmdc_pads_flowcharts_and_pie_charts() {
        let fs=MemoryVfs::new();
        for (source,padding,path,expected) in [
            ("flowchart TD; title Some longer chart title; A-->B", 56.5, "/d.svg","b489664b1cbf941a1670c266a63543eae1bd3f6e59ffe3e071ee5948205b3a73"),
            ("pie title Shipping\n\"Yes\":3\n\"No\":1", 56.5, "/d.svg","1f59d968466d6a353f3f2f6f50ca265600b6e06a2aeeb1287aaf9bbe110eb440"),
            ("flowchart LR; subgraph First; A-->B; end; B-->|passed|C", 56.5, "/d.pdf","0ddcd3e677a0986d51cd78ef879ba91f2e8df91b678094a5bc57e38f4f40dec1"),
            ("pie showData\n\"North\":8\n\"East\":4\n\"Other\":2", 17.25, "/d.png","85e5a9fb66d8f673059432a511cebac6ca640a7e5ebbf81865e2393d5006635d"),
        ] {
            fs.write_file("/config.json",format!(r#"{{"padding":{padding}}}"#).as_bytes()).unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-c","/config.json","-o",path]),source,"/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(r.exit_code,0,"{}",r.stderr);
            let bytes=fs.read_file(path).unwrap();
            assert_eq!(crate::commands::archive::sha256_bytes(&bytes).iter().map(|b|format!("{b:02x}")).collect::<String>(),expected);
        }
        fs.write_file("/config.json",br#"{"padding":17.25}"#).unwrap();
        fs.write_file("/d.svg",b"previous").unwrap();
        let r=try_run_structured_command("mmdc",&args(&["-c","/config.json","-i","-","-o","/d.svg"]),"flowchart TD; title Some longer chart title; A-->B","/",&BTreeMap::new(),&fs).unwrap();
        assert_eq!(r.exit_code,1);
        assert_eq!(r.stderr,"mmdc: E_LIMIT: Scene geometry verification failed: Invariant 1 (node clearance): nodes 'B' and 'mmdc_title' have clearance 18.00px (< 24px)\n");
        assert_eq!(fs.read_file("/d.svg").unwrap(),b"previous");
    }

