    #[test]
    fn mmdc_validates_backgrounds_after_parsing_before_rendering() {
        let fs=MemoryVfs::new();
        for (source,color,status,message) in [
            ("flowchart TD; A-->B","gray30",2,"E_CONFIG: Unsupported color format 'gray30'"),
            ("pie\n \"One\":1"," #aaaaa ",2,"E_CONFIG: Invalid hex color ' #aaaaa '"),
            ("flowchart TD; A-->","bogus",1,"E_SYNTAX (line 1, column 19): Expected node identifier at ''"),
            ("flowchart TD; A-->A; A-->A; B","bogus",2,"E_CONFIG: Unsupported color format 'bogus'"),
        ] {
            for path in ["/d.svg","/d.png","/d.pdf"] {
                fs.write_file(path,b"previous").unwrap();
                let result=try_run_structured_command("mmdc",&args(&["-i","-","-o",path,"-b",color]),source,"/",&BTreeMap::new(),&fs).unwrap();
                assert_eq!(result.exit_code,status);
                assert_eq!(result.stderr,format!("mmdc: {message}\n"));
                assert_eq!(fs.read_file(path).unwrap(),b"previous");
            }
        }
        let result=try_run_structured_command("mmdc",&args(&["-i","-","-o","/d.png","-b","rgb(0xff, 0, 1)"]),"flowchart LR; A-->B","/",&BTreeMap::new(),&fs).unwrap();
        assert_eq!(result.exit_code,0);
        let pixels=crate::commands::archive::sha256_bytes(&fs.read_file("/d.png").unwrap());
        assert_eq!(pixels.iter().map(|b|format!("{b:02x}")).collect::<String>(),"0349ed045c32daaef5e796406ad22280261dee587060401fbfa17c716d6b2889");
    }

    #[test]
    fn mmdc_rejects_invalid_flowchart_styles_before_writing() {
        let fs=MemoryVfs::new();
        for (source,status,message) in [
            ("flowchart TD; A-->B; style B stroke-width:-1px",1,"E_SYNTAX: Invalid stroke width"),
            ("flowchart TD; A-->B; style B fill:rgb(999, 2, 3)",2,"E_CONFIG: Out-of-range RGB/RGBA color 'rgb(999, 2, 3)'"),
            ("flowchart TD; A::: --> B",1,"E_SYNTAX (line 1, column 15): Missing inline class name"),
            ("flowchart TD; style A; A-->B",1,"E_SYNTAX (line 1, column 15): Missing style declaration"),
            ("flowchart TD; style A fill:#xyz; A-->B",2,"E_CONFIG: Invalid hex color '#xyz'"),
        ] {
            fs.write_file("/d.svg", b"previous").unwrap();
            let result=try_run_structured_command("mmdc",&args(&["-i","-","-o","/d.svg"]),source,"/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(result.exit_code,status);
            assert_eq!(result.stderr,format!("mmdc: {message}\n"));
            assert_eq!(fs.read_file("/d.svg").unwrap(),b"previous");
        }
    }

    #[test]
    fn mmdc_label_errors_preserve_the_destination() {
        let fs=MemoryVfs::new();
        for (source,message) in [
            ("flowchart TD; A-->B[\"onerror=foo\"]","E_UNSUPPORTED (line 1, column 19): Unsupported HTML or active content 'onerror=' in diagram label"),
            ("flowchart TD; A-->|<script>|B","E_UNSUPPORTED (line 1, column 16): Unsupported HTML or active content '<script' in diagram label"),
            ("flowchart TD; A --> B & {bad}","E_SYNTAX (line 1, column 25): Expected node identifier at '{bad}'"),
            ("%% head\n \tgraph W; A-->B","E_SYNTAX (line 2, column 9): Invalid flowchart direction 'W'. Supported: TB, TD, BT, LR, RL"),
            ("flowchart TD extra junk; A-->B","E_SYNTAX (line 1, column 14): Unexpected tokens after flowchart header: 'extra junk'"),
            ("flowchart; A-->B; direction NO","E_SYNTAX (line 1, column 19): Invalid direction 'NO'"),
            ("flowchart TD; title \"OnLoAd=foo\"; A-->B","E_UNSUPPORTED (line 1, column 15): Unsupported HTML or active content 'onload=' in diagram label"),
            ("flowchart TD; accDescr: <iframe; A-->B","E_UNSUPPORTED (line 1, column 15): Unsupported HTML or active content '<iframe' in diagram label"),
            (r#"flowchart TD; A-->B; click A "data:text/plain,hello""#,"E_UNSUPPORTED: Unsupported link URL scheme"),
            (r#"flowchart TD; A-->B; click A "JaVaScRiPt:run()""#,"E_UNSUPPORTED (line 1, column 22): Unsupported HTML or active content 'javascript:' in diagram label"),
            ("flowchart TD; subgraph G[<script>]; A; end","E_UNSUPPORTED (line 1, column 15): Unsupported HTML or active content '<script' in diagram label"),
            ("flowchart TD; subgraph G; A; end trailing","E_SYNTAX (line 1, column 30): Unexpected tokens after 'end': 'trailing'"),
            ("flowchart TD; A; end","E_SYNTAX (line 1, column 18): Unexpected 'end' without matching 'subgraph'"),
            ("flowchart TD; subgraph G; A","E_SYNTAX (line 1, column 1): Unclosed subgraph 'G' at end of diagram"),
            ("flowchart TD; 🦊-->","E_SYNTAX (line 1, column 20): Expected node identifier at ''"),
            ("flowchart TD; A[\"a\nb\"]-->|<script>|B","E_UNSUPPORTED (line 1, column 23): Unsupported HTML or active content '<script' in diagram label"),
            ("flowchart TD; A[Start","E_SYNTAX (line 1, column 15): Unclosed node shape '[...]'"),
            ("flowchart TD; A-->","E_SYNTAX (line 1, column 19): Expected node identifier at ''"),
            ("flowchart TD; A[\"unterminated","E_SYNTAX (line 1, column 15): Unterminated quoted string in diagram source"),
        ] {
            fs.write_file("/d.svg",b"previous").unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-o","/d.svg"]),source,"/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(r.exit_code,1);
            assert_eq!(r.stderr,format!("mmdc: {message}\n"));
            assert_eq!(fs.read_file("/d.svg").unwrap(),b"previous");
        }
    }

    #[test]
    fn mmdc_pie_validates_before_write_and_draws_each_slice() {
        let fs=MemoryVfs::new();
        for ext in ["svg","png","pdf"] {
            let path=format!("/pie.{ext}");
            fs.write_file(&path,b"previous").unwrap();
            let r=try_run_structured_command("mmdc",&args(&["-i","-","-o",&path]),"pie\n   \"X\": -1","/",&BTreeMap::new(),&fs).unwrap();
            assert_eq!(r.exit_code,1);
            assert_eq!(r.stderr,"mmdc: E_SYNTAX (line 2, column 4): Pie values must be finite nonnegative numbers\n");
            assert_eq!(fs.read_file(&path).unwrap(),b"previous");
        }
        let r=try_run_structured_command("mmdc",&args(&["-i","-","-o","/pie.svg"]),"pie showData title Split\n\"big\":3\n\"small\":1","/",&BTreeMap::new(),&fs).unwrap();
        assert_eq!(r.exit_code,0,"{}",r.stderr);
        let svg=String::from_utf8(fs.read_file("/pie.svg").unwrap()).unwrap();
        assert_eq!(svg.matches("class=\"mmdc-pie-slice\"").count(),2);
        assert!(svg.contains(">big [3] (75.0%)</text>") && svg.contains("<title>Split</title>"));
    }

